<?php

declare(strict_types=1);

namespace App\Entity;

use App\Enum\InviteStatus;
use App\Repository\InviteTokenRepository;
use Doctrine\DBAL\Types\Types;
use Doctrine\ORM\Mapping as ORM;
use Symfony\Component\Uid\Uuid;

/**
 * Represents a single-use friend invite token generated by an Admin.
 *
 * Security Model:
 * Only the SHA-256 hash of the 256-bit CSPRNG token is stored in the database.
 * The raw token is returned once to the Admin to share via an IM app.
 */
#[ORM\Entity(repositoryClass: InviteTokenRepository::class)]
#[ORM\Table(name: 'invite_tokens')]
#[ORM\UniqueConstraint(name: 'uniq_invite_token_hash', columns: ['token_hash'])]
class InviteToken
{
    #[ORM\Id]
    #[ORM\Column(type: 'uuid', unique: true)]
    private Uuid $id;

    /**
     * SHA-256 hash of the raw invite token (64 hex characters).
     */
    #[ORM\Column(name: 'token_hash', length: 64)]
    private string $tokenHash;

    /**
     * Admin user who generated this invite.
     */
    #[ORM\ManyToOne(targetEntity: User::class)]
    #[ORM\JoinColumn(name: 'created_by_id', nullable: false, onDelete: 'CASCADE')]
    private User $createdBy;

    /**
     * Member user who claimed this invite (null until claimed).
     */
    #[ORM\ManyToOne(targetEntity: User::class)]
    #[ORM\JoinColumn(name: 'claimed_by_id', nullable: true, onDelete: 'SET NULL')]
    private ?User $claimedBy = null;

    /**
     * Timestamp after which this invite cannot be claimed.
     */
    #[ORM\Column(name: 'expires_at', type: Types::DATETIME_IMMUTABLE)]
    private \DateTimeImmutable $expiresAt;

    /**
     * Timestamp when the invite was successfully claimed.
     */
    #[ORM\Column(name: 'claimed_at', type: Types::DATETIME_IMMUTABLE, nullable: true)]
    private ?\DateTimeImmutable $claimedAt = null;

    /**
     * Timestamp when the invite was revoked by an Admin prior to expiration.
     */
    #[ORM\Column(name: 'revoked_at', type: Types::DATETIME_IMMUTABLE, nullable: true)]
    private ?\DateTimeImmutable $revokedAt = null;

    #[ORM\Column(name: 'created_at', type: Types::DATETIME_IMMUTABLE)]
    private \DateTimeImmutable $createdAt;

    /**
     * @param string             $tokenHash SHA-256 hash of the raw token
     * @param User               $createdBy Admin issuing the invite
     * @param \DateTimeImmutable $expiresAt Expiration datetime
     */
    public function __construct(string $tokenHash, User $createdBy, \DateTimeImmutable $expiresAt)
    {
        $this->id = Uuid::v7();
        $this->tokenHash = $tokenHash;
        $this->createdBy = $createdBy;
        $this->expiresAt = $expiresAt;
        $this->createdAt = new \DateTimeImmutable();
    }

    public function getId(): Uuid
    {
        return $this->id;
    }

    public function getTokenHash(): string
    {
        return $this->tokenHash;
    }

    public function getCreatedBy(): User
    {
        return $this->createdBy;
    }

    public function getClaimedBy(): ?User
    {
        return $this->claimedBy;
    }

    public function getExpiresAt(): \DateTimeImmutable
    {
        return $this->expiresAt;
    }

    public function getClaimedAt(): ?\DateTimeImmutable
    {
        return $this->claimedAt;
    }

    public function getRevokedAt(): ?\DateTimeImmutable
    {
        return $this->revokedAt;
    }

    public function getCreatedAt(): \DateTimeImmutable
    {
        return $this->createdAt;
    }

    /**
     * Computes the current lifecycle state of this invite token.
     */
    public function getStatus(\DateTimeImmutable $now = new \DateTimeImmutable()): InviteStatus
    {
        if ($this->claimedAt !== null) {
            return InviteStatus::Claimed;
        }
        if ($this->revokedAt !== null) {
            return InviteStatus::Revoked;
        }
        if ($this->expiresAt <= $now) {
            return InviteStatus::Expired;
        }

        return InviteStatus::Pending;
    }

    /**
     * Determines whether the invite can currently be claimed.
     */
    public function isClaimable(\DateTimeImmutable $now = new \DateTimeImmutable()): bool
    {
        return $this->getStatus($now) === InviteStatus::Pending;
    }

    /**
     * Marks the invite as claimed by the newly provisioned friend user.
     */
    public function markClaimed(User $user, \DateTimeImmutable $now = new \DateTimeImmutable()): void
    {
        $this->claimedBy = $user;
        $this->claimedAt = $now;
    }

    /**
     * Revokes this invite, preventing any future claim.
     */
    public function revoke(\DateTimeImmutable $now = new \DateTimeImmutable()): void
    {
        $this->revokedAt = $now;
    }
}
